    ########################################################
    # src/databricks/labs/community_connector/sources/fin_ai/fin_ai.py
    ########################################################

    _SECONDS_PER_DAY = 86_400


    class FinAiLakeflowConnect(LakeflowConnect, SupportsPartitionedStream):
        """LakeflowConnect implementation for Fin.ai (Intercom REST API)."""

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)

            self._access_token = options.get("access_token")
            if not self._access_token:
                raise ValueError(
                    "Fin.ai connector requires 'access_token' (an Intercom private "
                    "app Access Token) in options"
                )

            region = (options.get("region") or "us").lower()
            if region not in BASE_URLS:
                raise ValueError(
                    f"Unsupported region {region!r}; expected one of {sorted(BASE_URLS)}"
                )
            self._base_url = BASE_URLS[region]

            # Optional connection-level lower bound for incremental backfills.
            self._start_epoch = self._parse_start_date(options.get("start_date"))

            # Re-read the last N days of each window every sync to catch late
            # ``updated_at`` mutations (mirrors Airbyte's lookback_window option).
            self._lookback_seconds = (
                self._non_negative_int(options.get("lookback_window"), 0) * _SECONDS_PER_DAY
            )

            # Self-throttle budget (requests/minute). Retained for parity with the
            # documented option; 429s are handled via Retry-After/X-RateLimit-Reset.
            self._api_rate_limit = self._non_negative_int(
                options.get("api_rate_limit"), 9500
            )

            # Freeze the upper bound at init time so incremental offsets stabilise
            # across microbatches within one Trigger.AvailableNow run.
            self._init_epoch = int(datetime.now(timezone.utc).timestamp())

        # ------------------------------------------------------------------
        # LakeflowConnect: schema / metadata
        # ------------------------------------------------------------------

        def list_tables(self) -> list[str]:
            """Static object list — Intercom has no single discovery endpoint."""
            return list(SUPPORTED_TABLES)

        def get_table_schema(
            self, table_name: str, table_options: dict[str, str]
        ) -> StructType:
            self._validate_table(table_name)
            return TABLE_SCHEMAS[table_name]

        def read_table_metadata(
            self, table_name: str, table_options: dict[str, str]
        ) -> dict:
            self._validate_table(table_name)
            return dict(TABLE_METADATA[table_name])

        # ------------------------------------------------------------------
        # SupportsPartitionedStream
        # ------------------------------------------------------------------

        def is_partitioned(self, table_name: str) -> bool:
            """Only the Search-API tables support range-query partitioning."""
            return table_name in PARTITIONED_TABLES

        def latest_offset(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
        ) -> dict:
            """Return the most recent offset available, capped at init time.

            Returning a fixed value (the init-time snapshot) across a trigger run
            is what lets Trigger.AvailableNow terminate: once the committed offset
            reaches this cap, subsequent calls return the same value and
            ``get_partitions`` yields no work.
            """
            self._validate_table(table_name)
            return {"cursor": self._init_epoch}

        def get_partitions(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
            end_offset: dict | None = None,
        ) -> Sequence[dict]:
            """Split the ``(start, end]`` ``updated_at`` range into time windows.

            Batch reads (``start_offset``/``end_offset`` both ``None``) partition
            the whole table from the configured floor up to the init-time cap.
            """
            self._validate_table(table_name)

            window_days = self._positive_int(
                table_options.get("window_days"), DEFAULT_WINDOW_DAYS
            )
            window_seconds = window_days * _SECONDS_PER_DAY

            lower = self._resolve_lower(start_offset)
            upper = self._resolve_upper(end_offset)
            if lower >= upper:
                return []

            # First-run optimisation: with no floor at all (no prior offset and no
            # start_date), a single open-ended partition avoids splitting all of
            # history back to the epoch into thousands of windows.
            if lower == 0:
                return [{"since": 0, "until": upper}]

            # Apply the lookback at partition-build time (not in the stored offset)
            # so the checkpointed cursor doesn't drift while still re-checking
            # recently-updated records.
            if self._lookback_seconds:
                lower = max(0, lower - self._lookback_seconds)
                if lower >= upper:
                    return []

            partitions: list[dict] = []
            cursor = lower
            while cursor < upper:
                nxt = min(cursor + window_seconds, upper)
                partitions.append({"since": cursor, "until": nxt})
                cursor = nxt
            return partitions

        def read_partition(
            self,
            table_name: str,
            partition: dict,
            table_options: dict[str, str],
        ) -> Iterator[dict]:
            """Read one ``(since, until]`` window of records on an executor."""
            self._validate_table(table_name)
            path, records_key = SEARCH_ENDPOINTS[table_name]
            since = int(partition["since"])
            until = int(partition["until"])
            yield from self._search_paginated(
                path, records_key, since, until, table_options
            )

        # ------------------------------------------------------------------
        # LakeflowConnect: read_table (single-driver path)
        # ------------------------------------------------------------------

        def read_table(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Single-driver read.

            Used by ``simpleStreamReader`` for the non-partitioned snapshot tables,
            and as a fallback for the Search-API tables when partitioning is not
            used.
            """
            self._validate_table(table_name)
            start_offset = start_offset or {}

            if table_name in PARTITIONED_TABLES:
                return self._read_search_fallback(table_name, start_offset, table_options)
            if table_name == "companies":
                return self._read_companies(start_offset, table_options)
            return self._read_snapshot(table_name, start_offset, table_options)

        # ------------------------------------------------------------------
        # Search-API reads
        # ------------------------------------------------------------------

        def _read_search_fallback(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Fallback single-driver incremental read for a Search-API table.

            Reads everything from the prior cursor up to the init-time cap in one
            batch, then advances the offset to the cap. The next call sees the
            cursor already at/past the cap and returns an empty batch with the same
            offset, terminating the trigger.
            """
            since = self._resolve_lower(start_offset)
            if since >= self._init_epoch:
                return iter([]), {"cursor": self._init_epoch}

            path, records_key = SEARCH_ENDPOINTS[table_name]
            query_since = max(0, since - self._lookback_seconds) if since > 0 else 0
            records = list(
                self._search_paginated(
                    path, records_key, query_since, self._init_epoch, table_options
                )
            )
            return iter(records), {"cursor": self._init_epoch}

        def _search_paginated(
            self,
            path: str,
            records_key: str,
            since: int,
            until: int,
            table_options: dict[str, str],
        ) -> Iterator[dict]:
            """Yield records from a POST search endpoint across cursor pages.

            The query bounds ``updated_at`` to ``(since, until]`` — an exclusive
            lower bound so back-to-back windows are disjoint, and an inclusive upper
            bound at the window end. ``since == 0`` means "beginning of time" and
            only the upper bound is applied.
            """
            per_page = self._positive_int(
                table_options.get("per_page"), DEFAULT_PER_PAGE
            )
            per_page = min(per_page, MAX_PER_PAGE)

            starting_after: str | None = None
            while True:
                # Intercom's Search API date predicates support only the strict
                # ``<`` / ``>`` operators — ``<=`` / ``>=`` are rejected with a 422
                # ``data_invalid`` ("Date predicate doesn't support comparison type
                # :lte"), as observed live on ``/contacts/search``. ``updated_at`` is
                # an integer number of epoch seconds, so the inclusive upper bound
                # ``updated_at <= until`` is expressed exactly as ``< until + 1``.
                # This keeps back-to-back windows disjoint: window ``(since, until]``
                # then ``(until, next]`` never double-counts or drops the boundary
                # second.
                filters = [{"field": "updated_at", "operator": "<", "value": until + 1}]
                if since > 0:
                    filters.append(
                        {"field": "updated_at", "operator": ">", "value": since}
                    )
                body: dict = {
                    "query": {"operator": "AND", "value": filters},
                    # ``sort`` is undocumented but relied on in production (Airbyte)
                    # to make paginated incremental reads deterministic.
                    "sort": {"field": "updated_at", "order": "ascending"},
                    "pagination": {"per_page": per_page},
                }
                if starting_after:
                    body["pagination"]["starting_after"] = starting_after

                resp = self._request_with_retry("POST", path, json_body=body)
                if resp.status_code != 200:
                    raise RuntimeError(
                        f"Intercom search failed for {path}: "
                        f"{resp.status_code} {resp.text[:500]}"
                    )

                data = resp.json()
                for record in self._extract_records(data, records_key):
                    yield record

                starting_after = self._next_starting_after(data)
                if not starting_after:
                    return

        # ------------------------------------------------------------------
        # Snapshot reads
        # ------------------------------------------------------------------

        def _read_companies(
            self, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Full-refresh read of companies via the Scroll API.

            The Scroll API iterates the entire company list with an opaque
            ``scroll_param``; there is no server-side time filter. All pages are
            drained in one ``read_table`` call and a ``{"done": True}`` sentinel is
            returned so a follow-up call in the same trigger short-circuits and the
            trigger terminates.
            """
            if start_offset.get("done"):
                return iter([]), start_offset

            records: list[dict] = []
            scroll_param: str | None = None
            for _ in range(MAX_SCROLL_PAGES):
                params: dict[str, str] = {}
                if scroll_param:
                    params["scroll_param"] = scroll_param

                resp = self._request_with_retry("GET", "/companies/scroll", params=params)
                if resp.status_code != 200:
                    raise RuntimeError(
                        f"Intercom companies/scroll failed: "
                        f"{resp.status_code} {resp.text[:500]}"
                    )

                body = resp.json()
                batch = self._extract_records(body, "data")
                if not batch:
                    break
                records.extend(batch)

                scroll_param = body.get("scroll_param")
                if not scroll_param:
                    break

            return iter(records), {"done": True}

        def _read_snapshot(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Full-refresh read of a simple single-call GET snapshot table."""
            if start_offset.get("done"):
                return iter([]), start_offset

            path, records_key = SNAPSHOT_ENDPOINTS[table_name]
            params: dict[str, str] = {}
            if table_name == "data_attributes":
                # Omitting ``model`` returns attributes for all models in one call;
                # each record carries its own ``model`` field.
                params["include_archived"] = table_options.get("include_archived", "false")
            elif table_name == "segments" and "include_count" in table_options:
                params["include_count"] = table_options["include_count"]
            elif table_name == "admins":
                params["display_avatar"] = table_options.get("display_avatar", "false")

            resp = self._request_with_retry("GET", path, params=params)
            if resp.status_code != 200:
                raise RuntimeError(
                    f"Intercom {path} failed: {resp.status_code} {resp.text[:500]}"
                )
            records = self._extract_records(resp.json(), records_key)
            return iter(records), {"done": True}

        # ------------------------------------------------------------------
        # HTTP layer
        # ------------------------------------------------------------------

        def _headers(self) -> dict[str, str]:
            return {
                "Authorization": f"Bearer {self._access_token}",
                "Accept": "application/json",
                "Content-Type": "application/json",
                "Intercom-Version": INTERCOM_VERSION,
            }

        def _request_with_retry(
            self,
            method: str,
            path: str,
            *,
            params: dict | None = None,
            json_body: dict | None = None,
        ) -> requests.Response:
            """Issue an HTTP request, retrying transient failures with backoff.

            Fresh ``requests`` calls are used per request (no cached ``Session``)
            so the connector instance stays picklable when shipped to executors.
            Rate limiting (429) honours ``Retry-After`` and falls back to
            ``X-RateLimit-Reset`` when present.
            """
            url = f"{self._base_url}{path}"
            backoff = INITIAL_BACKOFF
            resp: requests.Response | None = None
            last_exc: RequestException | None = None

            for attempt in range(MAX_RETRIES):
                try:
                    if method == "GET":
                        resp = requests.get(
                            url,
                            headers=self._headers(),
                            params=params,
                            timeout=DEFAULT_TIMEOUT,
                        )
                    elif method == "POST":
                        resp = requests.post(
                            url,
                            headers=self._headers(),
                            params=params,
                            json=json_body,
                            timeout=DEFAULT_TIMEOUT,
                        )
                    else:
                        raise ValueError(f"Unsupported HTTP method: {method}")
                except RequestException as exc:
                    last_exc = exc
                    resp = None
                else:
                    if resp.status_code not in RETRIABLE_STATUS_CODES:
                        return resp

                if attempt < MAX_RETRIES - 1:
                    time.sleep(self._retry_delay(resp, backoff))
                    backoff *= 2

            if resp is None and last_exc is not None:
                raise RuntimeError(
                    f"Intercom request failed after {MAX_RETRIES} attempts for "
                    f"{method} {path}: {last_exc}"
                ) from last_exc
            return resp  # type: ignore[return-value]

        @staticmethod
        def _retry_delay(resp: requests.Response | None, backoff: float) -> float:
            """Pick a retry delay, preferring server throttling hints."""
            if resp is None:
                return backoff
            retry_after = resp.headers.get("Retry-After", "").strip()
            if retry_after:
                try:
                    return max(backoff, float(retry_after))
                except ValueError:
                    pass
            # 429 with a reset timestamp: wait until the window resets.
            if resp.status_code == 429:
                reset = resp.headers.get("X-RateLimit-Reset", "").strip()
                if reset:
                    try:
                        wait = float(reset) - time.time()
                        if wait > 0:
                            return max(backoff, min(wait, 60.0))
                    except ValueError:
                        pass
            return backoff

        # ------------------------------------------------------------------
        # Helpers
        # ------------------------------------------------------------------

        def _validate_table(self, table_name: str) -> None:
            if table_name not in SUPPORTED_TABLES:
                raise ValueError(
                    f"Table '{table_name}' is not supported. "
                    f"Supported tables: {SUPPORTED_TABLES}"
                )

        def _resolve_lower(self, start_offset: dict | None) -> int:
            """Resolve the exclusive lower cursor bound (Unix seconds)."""
            if start_offset:
                cursor = start_offset.get("cursor")
                if cursor is not None:
                    return int(cursor)
            if self._start_epoch is not None:
                return self._start_epoch
            return 0

        def _resolve_upper(self, end_offset: dict | None) -> int:
            """Resolve the inclusive upper cursor bound (Unix seconds)."""
            if end_offset:
                cursor = end_offset.get("cursor")
                if cursor is not None:
                    return int(cursor)
            return self._init_epoch

        @staticmethod
        def _extract_records(body, records_key: str) -> list[dict]:
            """Extract a record list from a wrapped or bare-list response.

            Intercom's list/search envelopes vary by resource (``conversations`` /
            ``tickets`` / ``data`` / ``segments`` / ...), so try the expected key
            first, then the common fallbacks, then any top-level list value.

            Each record is normalised so that empty JSON objects (``{}``) become
            ``None`` — Intercom returns ``{}`` for absent nested objects (e.g. a
            company with no ``plan``), which Spark's StructType parser rejects
            ("field in StructType cannot be an empty dict"). Nulling them keeps the
            yielded records compatible with the declared struct schemas while
            leaving MapType columns (which accept empty maps) unaffected.
            """
            raw = FinAiLakeflowConnect._records_list(body, records_key)
            return [FinAiLakeflowConnect._null_empty_dicts(r) for r in raw]

        @staticmethod
        def _records_list(body, records_key: str) -> list[dict]:
            if isinstance(body, list):
                return body
            if not isinstance(body, dict):
                return []
            value = body.get(records_key)
            if isinstance(value, list):
                return value
            for fallback in ("data", "conversations", "tickets", "contacts"):
                value = body.get(fallback)
                if isinstance(value, list):
                    return value
            return []

        @staticmethod
        def _null_empty_dicts(value):
            """Recursively replace empty dicts (``{}``) with ``None``.

            Intercom emits ``{}`` for absent nested objects; a StructType column
            cannot ingest an empty dict, so it must be nulled. Non-empty dicts and
            lists are walked so nested absent objects are handled too.
            """
            if isinstance(value, dict):
                if not value:
                    return None
                return {
                    k: FinAiLakeflowConnect._null_empty_dicts(v)
                    for k, v in value.items()
                }
            if isinstance(value, list):
                return [FinAiLakeflowConnect._null_empty_dicts(v) for v in value]
            return value

        @staticmethod
        def _next_starting_after(body) -> str | None:
            """Read the next cursor from ``pages.next`` (dict or URL string)."""
            if not isinstance(body, dict):
                return None
            pages = body.get("pages")
            if not isinstance(pages, dict):
                return None
            nxt = pages.get("next")
            if isinstance(nxt, dict):
                return nxt.get("starting_after")
            if isinstance(nxt, str) and nxt:
                return nxt
            return None

        @staticmethod
        def _parse_start_date(value: str | None) -> int | None:
            """Parse an ISO-8601 ``start_date`` into Unix seconds, or ``None``."""
            if not value:
                return None
            text = value.strip()
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            dt = datetime.fromisoformat(text)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return int(dt.astimezone(timezone.utc).timestamp())

        @staticmethod
        def _positive_int(raw: str | None, default_value: int) -> int:
            try:
                value = int(raw) if raw is not None else default_value
            except (TypeError, ValueError):
                return default_value
            return value if value > 0 else default_value

        @staticmethod
        def _non_negative_int(raw: str | None, default_value: int) -> int:
            try:
                value = int(raw) if raw is not None else default_value
            except (TypeError, ValueError):
                return default_value
            return value if value >= 0 else default_value


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = FinAiLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
